    fn needs_php(name: &str, path: &str) -> SiteInfo {
        let mut site = php_site(name, path);
        site.project_file = Some(format!("{path}/.yard"));
        site.needs = vec![yard_proto::Need::Php { php: "7.3".into() }];
        site
    }

    fn page_text(page: &str) -> String {
        let start = page.find("<pre>").unwrap() + 5;
        page[start..page.find("</pre>").unwrap()].replace("&#39;", "'")
    }

